`timescale 1ns/1ps

// File-driven bit-exact Gate-C regression.  Expected beats are generated by
// generate_gate_c_hdl_vectors.py from the independent VTM10 Oracle.
module its_unified_submission_top_full_spatial_tb;
    parameter string VECTOR_FILE = "full_spatial_vectors.txt";

    logic clk = 1'b0;
    always #1 clk = ~clk;
    logic rst_n = 1'b0;
    logic [21:0] it_info = '0;
    logic it_info_vld = 1'b0;
    logic signed [15:0] it_data_in = '0;
    logic [11:0] it_data_addr = '0;
    logic it_data_in_vld = 1'b0;
    logic it_data_end = 1'b0;
    logic it_data_in_req;
    logic it_data_out_req = 1'b0;
    logic [39:0] it_data_out;
    logic it_data_out_vld;
    logic it_done;
    logic protocol_error;

    its_unified_submission_top dut (
        .clk(clk), .rst_n(rst_n),
        .it_info(it_info), .it_info_vld(it_info_vld),
        .it_data_in(it_data_in), .it_data_addr(it_data_addr),
        .it_data_in_vld(it_data_in_vld), .it_data_end(it_data_end),
        .it_data_in_req(it_data_in_req),
        .it_data_out_req(it_data_out_req),
        .it_data_out(it_data_out), .it_data_out_vld(it_data_out_vld),
        .it_done(it_done)
    );

    assign protocol_error = dut.u_unified_wrapper.protocol_error;

    task automatic send_info(input logic [21:0] value);
        begin
            @(negedge clk);
            it_info = value;
            it_info_vld = 1'b1;
            @(posedge clk);
            @(negedge clk);
            it_info_vld = 1'b0;
        end
    endtask

    task automatic send_data(input integer address, input integer value,
                             input bit last);
        begin
            while (!it_data_in_req) @(negedge clk);
            it_data_addr = address[11:0];
            it_data_in = value[15:0];
            it_data_in_vld = 1'b1;
            it_data_end = last;
            @(posedge clk);
            @(negedge clk);
            it_data_in_vld = 1'b0;
            it_data_end = 1'b0;
        end
    endtask


    integer v_commands=0,v_commits=0,v_last_commits=0,expected_v_groups;
    bit h_verified=0;
    bit [1023:0] seen_v_addr[0:3];
    integer forced_left;bit half_stalled,last_stalled;
    function automatic integer expected_cut_width(input logic[21:0] d);
        integer w,h,t;
        begin
            w=d[6:0];h=d[13:7];t=d[15:14];
            if(d[21:20]!=0) expected_cut_width=(w==4 || h==4)?4:8;
            else if(t!=0 && w==32) expected_cut_width=16;
            else expected_cut_width=(w>32)?32:w;
        end
    endfunction
    always @(posedge clk) begin
        if(rst_n) begin
            if(dut.u_unified_wrapper.vertical_result_fire) v_commands=v_commands+1;
            if(dut.u_unified_wrapper.vwrite_cmd_commit) begin
                v_commits=v_commits+1;
                if(dut.u_unified_wrapper.vwrite_cmd_last_q) v_last_commits=v_last_commits+1;
                if(dut.u_unified_wrapper.vwrite_cmd_addr_q>=1024 ||
                   dut.u_unified_wrapper.vwrite_cmd_bank_mask_q!==4'b1111)
                    $fatal(1,"bad full spatial V write address/mask");
                for(integer b=0;b<4;b=b+1) begin
                    if(seen_v_addr[b][dut.u_unified_wrapper.vwrite_cmd_addr_q])
                        $fatal(1,"duplicate full spatial intermediate write");
                    seen_v_addr[b][dut.u_unified_wrapper.vwrite_cmd_addr_q]=1;
                end
            end
            if(dut.u_unified_wrapper.kernel_phase_q==4'd5 && !h_verified) begin
                if(v_commits!=expected_v_groups || v_commands!=expected_v_groups || v_last_commits!=1)
                    $fatal(1,"H before complete V commit got=%0d want=%0d last=%0d",v_commits,expected_v_groups,v_last_commits);
                h_verified=1;
            end
        end
    end

    integer vector_fd;
    integer scan_rc;
    integer case_count;
    integer case_index;
    integer input_count;
    integer beat_count;
    integer input_index;
    integer beat_index;
    integer request_cycle;
    integer total_beats = 0;
    integer pending_stall_cycles = 0;
    integer done_count;
    integer input_addr [0:4095];
    integer input_value[0:4095];
    logic [39:0] expected_beat[0:1023];
    logic [21:0] case_desc;
    logic [39:0] held_data;
    bit holding;
    bit fire_now;
    bit last_now;

    initial begin
        vector_fd = $fopen(VECTOR_FILE, "r");
        if (vector_fd == 0)
            $fatal(1, "cannot open vector file %s", VECTOR_FILE);
        scan_rc = $fscanf(vector_fd, "%d", case_count);
        if (scan_rc != 1)
            $fatal(1, "invalid vector header");

        repeat (3) @(negedge clk);
        rst_n = 1'b1;

        for (case_index = 0; case_index < case_count;
             case_index = case_index + 1) begin
            scan_rc = $fscanf(vector_fd, "%h %d %d",
                              case_desc, input_count, beat_count);
            if (scan_rc != 3 || input_count > 4096 || beat_count > 1024)
                $fatal(1, "invalid case header case=%0d", case_index);
            for (input_index = 0; input_index < input_count;
                 input_index = input_index + 1) begin
                scan_rc = $fscanf(vector_fd, "%d %d",
                                  input_addr[input_index],
                                  input_value[input_index]);
                if (scan_rc != 2)
                    $fatal(1, "invalid input row case=%0d input=%0d",
                           case_index, input_index);
            end
            for (beat_index = 0; beat_index < beat_count;
                 beat_index = beat_index + 1) begin
                scan_rc = $fscanf(vector_fd, "%h", expected_beat[beat_index]);
                if (scan_rc != 1)
                    $fatal(1, "invalid expected row case=%0d beat=%0d",
                           case_index, beat_index);
            end

            v_commands=0;v_commits=0;v_last_commits=0;h_verified=0;
            expected_v_groups=expected_cut_width(case_desc)*(case_desc[13:7]>>2);
            for(integer b=0;b<4;b=b+1) seen_v_addr[b]='0;
            send_info(case_desc);
            if(input_count==0) begin
                while(!it_data_in_req) @(negedge clk);
                it_data_end=1;
                @(posedge clk);
                @(negedge clk);it_data_end=0;
            end
            for (input_index = 0; input_index < input_count;
                 input_index = input_index + 1)
                send_data(input_addr[input_index], input_value[input_index],
                          input_index == input_count - 1);

            beat_index = 0;
            request_cycle = 0;
            done_count = 0;
            holding = 1'b0;
            forced_left=0;half_stalled=0;last_stalled=0;
            while (beat_index < beat_count) begin
                @(negedge clk);
                it_data_out_req = ((request_cycle + case_index) % 7 != 2) &&
                                  ((request_cycle + case_index) % 11 != 5);
                if(beat_index==beat_count/2 && !half_stalled) begin
                    forced_left=4;half_stalled=1;
                end
                if(beat_index==beat_count-1 && !last_stalled) begin
                    forced_left=4;last_stalled=1;
                end
                if(forced_left>0) begin it_data_out_req=0;forced_left=forced_left-1;end
                request_cycle = request_cycle + 1;
                if (request_cycle > 200000) $fatal(1, "top numeric timeout");
                #0;
                if (!it_data_out_req) begin
                    if (it_data_out_vld)
                        $fatal(1, "out_valid asserted under stall case=%0d",
                               case_index);
                    if (dut.u_unified_wrapper.output_active) begin
                        if (holding && it_data_out !== held_data)
                            $fatal(1, "hold changed case=%0d beat=%0d",
                                   case_index, beat_index);
                        pending_stall_cycles = pending_stall_cycles + 1;
                        held_data = it_data_out;
                        holding = 1'b1;
                    end else begin
                        holding = 1'b0;
                    end
                end else begin
                    holding = 1'b0;
                end

                @(posedge clk);
                fire_now = it_data_out_vld && it_data_out_req;
                last_now = fire_now && (beat_index == beat_count - 1);
                if (it_done !== last_now)
                    $fatal(1,
                           "done/fire mismatch case=%0d beat=%0d done=%0b last=%0b",
                           case_index, beat_index, it_done, last_now);
                if (fire_now) begin
                    if (it_data_out !== expected_beat[beat_index])
                        $fatal(1,
                               "numeric mismatch case=%0d beat=%0d got=%010h expected=%010h",
                               case_index, beat_index, it_data_out,
                               expected_beat[beat_index]);
                    done_count = done_count + it_done;
                    beat_index = beat_index + 1;
                    total_beats = total_beats + 1;
                end
                if (protocol_error)
                    $fatal(1, "protocol_error case=%0d", case_index);
            end
            if(!h_verified || v_commits!=expected_v_groups || v_last_commits!=1)
                $fatal(1,"full spatial V write coverage missing case=%0d",case_index);
            if (done_count != 1)
                $fatal(1, "done count mismatch case=%0d count=%0d",
                       case_index, done_count);
            @(posedge clk);
            if (it_done)
                $fatal(1, "done pulse wider than one edge case=%0d", case_index);
            @(negedge clk);
            it_data_out_req = 1'b0;
        end

        $fclose(vector_fd);
        if (pending_stall_cycles == 0) $fatal(1, "no real pending-output stall");
        $display("FULL_SPATIAL_NUMERIC_PASS cases=%0d beats=%0d pending_stall_cycles=%0d", case_count, total_beats, pending_stall_cycles);
        $finish;
    end
endmodule



